Translate("zhCN", "arathi-highlands", {
	title = "阿拉希高地",
	aliases = { "阿拉希" },
	sections = {
		{
			title = "概述",
			text = [=[阿拉希高地是一片高旷而干燥的土地，遍布青草、风与灰色岩石，位于{link:hillsbrad-foothills}希尔斯布莱德丘陵{/link}与{link:the-hinterlands}辛特兰{/link}之间。{link:humans}人类{/link}正是在这里第一次成为一个国家。当人类诸{link:horde}部落{/link}仍在与{link:trolls}巨魔{/link}交战时，{link:stromgarde-keep}斯托姆{/link}要塞便在这片{link:burning-steppes}平原{/link}上拔地而起，世间所有的人类王国都源自于它。如今，{link:razorfen-downs}高地{/link}不属于任何人。沿用斯托姆之名的王国激流堡已沦为废墟。{link:orcs}兽人{/link}占据着东部丘陵上的{link:hammerfall}落锤镇{/link}，而那片土地正是{link:alliance}联盟{/link}当年将他们锁上镣铐的地方。激流堡最后的士兵们在{link:refuge-pointe}避难谷地{/link}等待着重返家园的那一天。]=],
		},
		{
			title = "起源",
			text = [=[大约在{link:dark-portal}黑暗之门{/link}开启前二十八个世纪，北方的{link:humans}人类{/link}{link:horde}部落{/link}四散分布，彼此征战，而阿曼尼{link:trolls}巨魔{/link}则对他们所有人肆意猎杀。阿拉希部族的军事领袖{link:thoradin}索拉丁{/link}将诸部落联合起来，在这片{link:razorfen-downs}高地{/link}上筑起了{link:stromgarde-keep}斯托姆{/link}要塞。开阔干旱的土地让巨魔无法施展他们惯用的林间伏击。在斯托姆，{link:quel-thalas}奎尔萨拉斯{/link}的精灵向一百名人类传授了{link:arcane-magic}魔法{/link}之道，两个种族携手在{link:troll-wars}巨魔战争{/link}中击溃了阿曼尼。此后的数个世纪里，{link:arathor}阿拉索{/link}帝国扩展到整片大陆，并将它的第一座城市留在了身后。名门望族北迁，索拉丁血脉的最后传人则航向南方，建立了后来成为{link:stormwind-city}暴风城{/link}的王国。托尔{link:baine-bloodhoof}贝恩{/link}家族是巨魔战争中一位将军的后裔，他们留了下来，并将这座古城命名为激流堡。]=],
		},
		{
			title = "当今",
			text = [=[{link:thoras-trollbane}国王索拉斯{/link}·托尔{link:baine-bloodhoof}贝恩{/link}已经死去，他的城市化为一片废墟。{link:boulderfist-ogres}石拳食人魔{/link}与{link:syndicate}辛迪加{/link}的匪徒占据了{link:stromgarde-keep}激流堡{/link}的大部分地区，王国军队的残部在{link:prince-galen-trollbane}加林·托尔贝恩王子{/link}的率领下死守着仅剩的一个城区。在{link:refuge-pointe}避难谷地{/link}，{link:captain-nials}尼艾丝队长{/link}召集着残存的力量，{link:league-of-arathor}阿拉索联军{/link}则准备以武力夺回这片土地。东方的{link:hammerfall}落锤镇{/link}已成为{link:horde}部落{/link}的前哨。那里的{link:orcs}兽人{/link}正在抵御联手对付他们的{link:witherbark-trolls}枯木巨魔{/link}和石拳食人魔。{link:vol-jin}沃金{/link}派出的{link:darkspear-trolls}暗矛{/link}猎手在托尔贝恩家族的陵墓中寻找一柄古剑，{link:forsaken}被遗忘者{/link}的{link:defilers}污染者{/link}则在争夺富饶的{link:arathi-basin}阿拉希盆地{/link}。在大地深处，一个声音正透过水晶碎片发出呼唤，乞求自由。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:stromgarde-keep}激流堡{/link}的士兵。{/b}王国军队的最后残部，分驻于首都废墟和{link:refuge-pointe}避难谷地{/link}的营地。
• {b}{link:hammerfall}落锤镇{/link}的{link:horde}部落{/link}。{/b}{link:orcs}兽人{/link}、{link:darkspear-trolls}暗矛巨魔{/link}与{link:forsaken}被遗忘者{/link}，与{link:razorfen-downs}高地{/link}上的其他所有势力为敌。
• {b}{link:syndicate}辛迪加{/link}。{/b}效命于{link:alterac-mountains}奥特兰克{/link}没落领主的盗贼与术士。
• {b}{link:boulderfist-ogres}石拳食人魔{/link}。{/b}高地上最庞大的一支力量，从{link:boulder-gor}博德戈尔{/link}一直分布到{link:boulderfist-hall}石拳大厅{/link}。
• {b}{link:witherbark-trolls}枯木巨魔{/link}。{/b}东南部的森林{link:trolls}巨魔{/link}，斯托姆最古老的敌人。
• {b}{link:drywhisker-kobolds}枯须狗头人{/link}。{/b}东部峡谷中的挖掘者，也是巨人的盟友。
• {b}黑水袭击者。{/b}来自{link:booty-bay}藏宝海湾{/link}的海盗，搁浅在{link:faldir-s-cove}法迪尔海湾{/link}。]=],
		},
		{
			title = "历史",
			text = [=[• {b}{link:arathor}阿拉索{/link}。{/b}{link:thoradin}索拉丁{/link}统一诸{link:horde}部落{/link}，建立{link:stromgarde-keep}斯托姆{/link}。{link:humans}人类{/link}从这里出发，建立起自己的王国。
• {b}七大王国。{/b}斯托姆衰落之后，贵族与王室血脉相继离去。托尔{link:baine-bloodhoof}贝恩{/link}家族留了下来，统治激流堡。
• {b}{link:second-war}第二次战争{/link}。{/b}{link:thoras-trollbane}索拉斯·托尔贝恩{/link}率领激流堡加入了{link:lordaeron}洛丹伦{/link}{link:alliance}联盟{/link}。
• {b}{link:internment-camps}收容所{/link}。{/b}战后，联盟将战败的{link:orcs}兽人{/link}关押在东部丘陵的一座收容所里。{link:thrall}萨尔{/link}与{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}攻破了它，毁灭之锤也在那里倒下。
• {b}陷落。{/b}洛丹伦沦陷之后，激流堡落入{link:ogres}食人魔{/link}与匪徒之手，城中百姓四散流离。]=],
		},
		{
			title = "高地传说",
			text = [=[• 四座立石环分布在{link:razorfen-downs}高地{/link}各处。大地、火焰、流水与空气的灵魂在其间行走。
• {link:refuge-pointe}避难谷地{/link}的士兵发誓，在国王的旗帜再度飘扬于{link:stromgarde-keep}激流堡{/link}之上以前，绝不离开高地。
• {link:hammerfall}落锤镇{/link}的{link:orcs}兽人{/link}说，他们营地土地上的那块黑色污迹，是{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}的鲜血。]=],
		},
	},
})

Translate("zhCN", "stromgarde-keep", {
	title = "激流堡",
	aliases = { "激流堡", "斯托姆" },
	sections = {
		{
			title = "概述",
			text = [=[激流堡位于{link:razorfen-downs}高地{/link}西南部，是{link:humans}人类{/link}第一座城市斯托姆仅存的遗迹。如今，它的城墙之内同时驻扎着三支军队。{link:boulderfist-ogres}石拳食人魔{/link}及其{link:witherbark-trolls}枯木{/link}盟友占据了城市的大片区域，并盘踞在{link:arathor}阿拉索{/link}之塔中，大法师{link:trey-lightforge}特雷{/link}{link:raene-wolfrunner}莱恩{/link}曾在那里坚守到最后一刻，然后才逃离。{link:syndicate}辛迪加{/link}在{link:lord-falconcrest}法库雷斯特公爵{/link}的统领下占据了另一个城区。激流堡最后的士兵在{link:prince-galen-trollbane}加林·托尔贝恩王子{/link}的率领下守卫着礼拜堂周围的街区。礼拜堂后方便是密室，{link:thoras-trollbane}国王索拉斯{/link}与宝剑{link:trol-kalar}托卡拉尔{/link}一同长眠在一座封印的陵墓之中。]=],
		},
		{ title = "僵局", text = "三方谁也无法驱逐其他两方。每一方都在同时与两个对手作战，这座城市每天都在流失更多的鲜血。" },
	},
})

Translate("zhCN", "refuge-pointe", {
	title = "避难谷地",
	sections = {
		{
			title = "概述",
			text = [=[避难谷地是{link:razorfen-downs}高地{/link}中央一座山丘上的设防营地。首都陷落之后，{link:stromgarde-keep}激流堡{/link}军队的残部便驻扎于此。{link:captain-nials}尼艾丝队长{/link}在这里指挥，她的士兵发誓在夺回城市之前绝不离开高地。当{link:syndicate}辛迪加{/link}放行时，补给会沿着道路从{link:southshore}南海镇{/link}运上来。近来营地里插满了新的旗帜：{link:league-of-arathor}阿拉索联军{/link}正在这里集结，准备争夺{link:arathi-basin}阿拉希盆地{/link}。一位{link:stormwind-city}暴风城{/link}大法师的两名使者也在谷地扎下了帐篷。]=],
		},
	},
})

Translate("zhCN", "hammerfall", {
	title = "落锤镇",
	sections = {
		{
			title = "概述",
			text = [=[落锤镇坐落在{link:razorfen-downs}高地{/link}东部的丘陵上。{link:second-war}第二次战争{/link}之后，这里是{link:alliance}联盟{/link}关押战败{link:orcs}兽人{/link}的{link:internment-camps}收容所{/link}之一。它的牢笼、枷锁与绞架至今依然矗立。{link:thrall}萨尔{/link}与{link:orgrim-doomhammer}奥格瑞姆·毁灭之锤{/link}曾来此解放囚徒，毁灭之锤就在这里被一名骑士的长枪从背后刺倒。多年以后，兽人重返此地，将这片废墟据为己有。如今，{link:drum-fel}杜拉姆法尔{/link}为{link:horde}部落{/link}镇守落锤镇，麾下有{link:darkspear-trolls}暗矛巨魔{/link}、{link:defilers}被遗忘者污染者{/link}，还有一位部落的首席医师。{link:trolls}巨魔{/link}和{link:ogres}食人魔{/link}无休无止地冲击着它的城墙。]=],
		},
	},
})

Translate("zhCN", "go-shek-farm", {
	title = "格沙克农场",
	sections = {
		{
			title = "概述",
			text = [=[格沙克农场位于东部低地，在{link:hammerfall}落锤镇{/link}的西南方。落锤镇的苦工在{link:orcs}兽人{/link}步兵的监视下耕作田地，收成供养着这座前哨。但农场里藏着的不只是粮食。在农场南缘的一座小屋里，{link:forsaken}被遗忘者{/link}药剂师乔{link:farmer-ray}雷{/link}尔正在进行致命的实验，一名信使将他的研究成果向西送往{link:tarren-mill}塔伦米尔{/link}。{link:phin-odelic}费恩·奥德利克{/link}的两名同伴已经在山上监视这座农场好几天了。]=],
		},
	},
})

Translate("zhCN", "circle-of-inner-binding", {
	title = "内禁锢法阵",
	sections = {
		{
			title = "概述",
			text = [=[内禁锢法阵是{link:stromgarde-keep}激流堡{/link}东北方{link:burning-steppes}平原{/link}上的一圈立石。法阵中央矗立着内禁锢之石，它是四块禁锢之石中最强大的一块，这四块石头将某种东西牢牢钉在{link:razorfen-downs}高地{/link}深处。石旁放着一块充满大地之力的拱心石。岩石之灵作为流放者在法阵中游荡，不容任何人靠近。没有任何编年史记载这些石头是由谁、在何时竖立的。]=],
		},
	},
