Translate("zhCN", "faldir-s-cove", {
	title = "法迪尔海湾",
	sections = {
		{
			title = "概述",
			text = [=[法迪尔海湾是南部海岸上的一个小港湾，位于{link:stromgarde-keep}激流堡{/link}以西的悬崖之下。{link:booty-bay}藏宝海湾{/link}{red:blackwater-raiders}黑水袭击者{/red}的三艘船来到这里，寻找一批失落的精灵宝藏。只有奥布{link:farmer-ray}雷{/link}恩船长的{i}先驱者号{/i}抵达了岸边。当其他船只随后驶来时，大海发出轰鸣，潮水退去，{i}{link:silverpine-forest}银松{/link}之魂号{/i}与{i}少女的愚行号{/i}在{link:the-vile-reef}暗礁{/link}上撞得粉碎。水下暗礁的刺脊{link:naga}纳迦{/link}杀死了大部分幸存者。搁浅的船员如今在海滩上扎营。]=],
		},
	},
})

Translate("zhCN", "witherbark-village", {
	title = "枯木村",
