			title = "概述",
			text = [=[枯木村是{link:razorfen-downs}高地{/link}东南部{link:witherbark-trolls}枯木巨魔{/link}的家园。他们的小屋散布在丘陵之间，巫医、猎头者和暗影猎手在那里延续着本族的古老传统。村子后方是枯木洞穴，部族的战团首领们在那里聚集。{link:trolls}巨魔{/link}从这里出发袭击{link:hammerfall}落锤镇{/link}，{link:drum-fel}杜拉姆法尔{/link}也正是把他的第一批士兵派到这里进行反击。]=],
		},
	},
})

Translate("zhCN", "boulderfist-hall", {
	title = "石拳大厅",
