		},
	},
})

Translate("zhCN", "boulder-gor", {
	title = "博德戈尔",
	sections = {
		{
			title = "概述",
			text = [=[博德戈尔是{link:stromgarde-keep}激流堡{/link}东北方丘陵上的一座{link:ogres}食人魔{/link}土丘。住在那里的{link:boulderfist-ogres}石拳食人魔{/link}比{link:boulderfist-hall}石拳大厅{/link}的同族更少、也更弱，但{link:witherbark-trolls}枯木巨魔{/link}与他们共用营地，两族一同出动劫掠。对{link:horde}部落{/link}而言，博德戈尔已成为一场考验。{link:tarren-mill}塔伦米尔{/link}的塔洛会先把新来的战士派到这里，只有活着回来的人才会被送往{link:hammerfall}落锤镇{/link}。一个名叫考沃克的食人魔在土丘周围的山丘上徘徊。]=],
		},
	},
})

Translate("zhCN", "dabyrie-s-farmstead", {
	title = "达比雷农场",
