Translate("zhCN", "drywhisker-gorge", {
	title = "枯须峡谷",
	sections = {
		{
			title = "概述",
			text = [=[枯须峡谷深入{link:razorfen-downs}高地{/link}最东北部的群山，位于{link:hammerfall}落锤镇{/link}之外。{link:drywhisker-kobolds}枯须狗头人{/link}在峡谷中挖满了隧道，到处是他们的勘测员和挖掘工，一个名叫燧石匕首的{link:kobolds}狗头人{/link}地卜师在其中操纵火焰。峡谷深处矗立着一簇闪闪发光的水晶碎片。狗头人守护着它，并随身携带着蕴含奇异力量的微粒。高地之下的那个声音称他们为囚禁她的人的盟友。]=],
