Translate("zhCN", "arathi-basin", {
	title = "阿拉希盆地",
	sections = {
		{
			title = "概述",
			text = [=[阿拉希盆地是{link:razorfen-downs}高地{/link}中心一处群山环绕的{link:stranglethorn-vale}山谷{/link}，是{link:eastern-kingdoms}东部王国{/link}最肥沃的土地之一。它的农场、矿洞、伐木场、铁匠铺和兽栏都是为供养一个王国而建。如今，两支军队正在为争夺它们而战。{link:league-of-arathor}阿拉索联军{/link}占据着托尔{link:baine-bloodhoof}贝恩{/link}大厅，意图为{link:stormwind-city}暴风城{/link}和{link:alliance}联盟{/link}赢得盆地的财富。{link:defilers}被遗忘者污染者{/link}占据着污染者之穴，意图切断{link:humans}人类{/link}与南方{link:dwarves}矮人{/link}盟友之间的联系。他们的道路分别通向{link:refuge-pointe}避难谷地{/link}和{link:hammerfall}落锤镇{/link}。]=],
		},
	},
})

Translate("zhCN", "captain-nials", {
	title = "尼艾丝队长",
	subtitle = "避难谷地指挥官",
	found = "避难谷地",
