			text = [=[尼艾丝队长在{link:refuge-pointe}避难谷地{/link}指挥着{link:stromgarde-keep}激流堡{/link}的士兵。她没有城市可以守卫，只有夺回城市的希望。她的军队日渐减员，敌人却日益壮大；每一周，{link:ogres}食人魔{/link}、{link:syndicate}辛迪加{/link}与她自己的民兵都在首都废墟中陷入更加血腥的僵持。]=],
		},
		{
			title = "意义",
			text = [=[尼亚斯是一个拒绝消亡的王国的声音。当{link:thandol-span}萨多尔大桥{/link}的{link:dwarves}矮人{/link}恳求她派兵时，她怀着悲痛拒绝了他们。她说，荣誉让她的军队留在{link:razorfen-downs}高地{/link}，直到国王的旗帜再次在{link:stromgarde-keep}激流堡{/link}上空升起。]=],
		},
		{
			title = "事迹",
			text = [=[• 她派遣战士前往{link:northfold-manor}诺斯弗德农场{/link}对抗{link:syndicate}辛迪加{/link}，以保持从{link:southshore}南海镇{/link}而来的补给道路畅通。
• 她为从辛迪加手中夺回的阵亡民兵徽章支付报酬，好让死者的家人知道他们的下落。
• 她悬赏缉拿辛迪加术士{link:marez-cowl}玛雷兹·考尔{/link}、{link:lord-falconcrest}法库雷斯特公爵{/link}及其保镖奥托。]=],
		},
		{
			title = "未载之事",
			text = [=[{link:refuge-pointe}避难谷地{/link}的记录只留下了她的军衔和事迹。关于她在城市陷落之前的生活，没有任何记载。]=],
		},
	},
	chapters = {
		{
			title = "来自大桥的求援",
			hint = "将湿地矮人的求援带到避难谷地。",
			text = [=[{link:dun-modr}丹莫德{/link}的{link:dwarves}矮人{/link}失去了他们的城镇和半座大桥，于是向{link:refuge-pointe}避难谷地{/link}求援。尼亚斯怀着沉重的心情听到了{link:thandol-span}萨多尔大桥{/link}的消息。然而她无力相助。{link:stromgarde-keep}激流堡{/link}已经陷落，她手中的每一把剑都要用来夺回它。她传话说，矮人们只能独自坚守。]=],
		},
		{
			title = "阵亡者的徽章",
			hint = "夺回辛迪加从激流堡死者身上拿走的东西。",
			text = [=[{link:syndicate}辛迪加{/link}每收到一枚从阵亡民兵身上割下的{link:stromgarde-keep}激流堡{/link}徽章，就付给手下的乌合之众一笔{link:ginro-hearthkindle}金{/link}币。尼亚斯不愿让匪徒从她的死者身上获利。徽章送回来后，她没有把它们当作战利品挂起来。她给每一个家庭捎去消息，告诉他们自家的士兵战死沙场，因为她认为，残酷的消息也比沉默更仁慈。]=],
		},
	},
	mentions = {
		{ text = "《向{link:alliance}联盟{/link}求援》，{link:dwarves}矮人{/link}的请求" },
		{ text = "{link:northfold-manor}诺斯弗德农场{/link}" },
		{ text = "{link:stromgarde-keep}激流堡{/link}徽章" },
		{ text = "通缉：{link:marez-cowl}玛雷兹·考尔{/link}" },
		{ text = "通缉：奥托和{link:lord-falconcrest}法库雷斯特{/link}" },
	},
	bonds = {
		{ id = "rhag-garmason", name = "拉格·加玛森", note = "向她求兵" },
		{ id = "longbraid-the-grim", name = "坚毅者长须", note = "她无力相助的矮人" },
		{ id = "lord-falconcrest", name = "法库雷斯特公爵", note = "被悬赏缉拿的敌人" },
		{ id = "marez-cowl", name = "玛雷兹·考尔", note = "被悬赏缉拿的敌人" },
		{ id = "prince-galen-trollbane", name = "加林·托尔贝恩王子", note = "她在废墟中的王子" },
	},
})

