Translate("zhCN", "prince-galen-trollbane", {
	title = "加林·托尔贝恩王子",
	subtitle = "激流堡的继承人",
	found = "激流堡守军城区的礼拜堂",
	hint = "寻找坚守激流堡最后一个城区的王子。",
	allegiance = "激流堡王国",
	aliases = { "加林·托尔贝恩王子", "加林" },
	sections = {
		{
			title = "概述",
			text = [=[加林·托尔贝恩王子是{link:thoras-trollbane}国王索拉斯{/link}之子，一个已倾覆王座的继承人。他坚守着{link:stromgarde-keep}激流堡{/link}中仍属于他的最后一角，也就是老城礼拜堂周围的一个街区。他的父亲就长眠在那座礼拜堂后面的陵墓中。加林守护着这座陵墓，也守护着陵墓中的那柄剑。]=],
		},
		{
			title = "意义",
			text = [=[加林是{link:razorfen-downs}高地{/link}上托尔{link:baine-bloodhoof}贝恩{/link}王子家族的最后一人，属于伊格纳乌斯的血脉，正是伊格纳乌斯在对抗{link:trolls}巨魔{/link}的战争中赢得了宝剑{link:trol-kalar}托卡拉尔{/link}。对{link:horde}部落{/link}的巨魔而言，他的血脉是古老的宿敌。对他的士兵而言，他是他们的国王留下的一切。]=],
		},
		{
			title = "事迹",
			text = [=[• 他用徽记封印了父亲的陵墓，并把徽记分给了{link:stromgarde-keep}激流堡{/link}的幸存者。
