			text = [=[密斯莱尔是{link:razorfen-downs}高地{/link}的秘密。{link:twilight-s-hammer}暮光之锤{/link}称她为“女士”，并为她的回归而效力。那个带着她的卷轴逃离教团的人则相信，巨人们禁锢她是有原因的，绝不能让她变得强大。]=],
