			text = [=[{link:azeroth}艾泽拉斯{/link}的任何编年史都没有提到过密斯莱尔。她是什么、来自何方、巨人为何要禁锢她，人们只能从她自己的话语和{link:theldurin-the-lost}迷失者塞尔杜林{/link}的话语中得知。]=],
