Translate("zhCN", "thoradin", {
	title = "索拉丁",
	subtitle = "阿拉索的第一位国王",
	allegiance = "阿拉希部族 · 阿拉索",
	sections = {
		{
			title = "概述",
			text = [=[索拉丁是{link:arathi-highlands}阿拉希{/link}部族的军事领袖，是他使{link:humans}人类{/link}成为了一个国家。在那个时代，北方的人类{link:horde}部落{/link}互相攻伐，而{link:trolls}巨魔{/link}则猎杀着他们所有人；他将他们团结在同一面旗帜之下。他将这个新王国命名为{link:arathor}阿拉索{/link}，并在以他的部族命名的{link:razorfen-downs}高地{/link}上建起了都城{link:stromgarde-keep}斯托姆{/link}。当今的每一个人类王国都源自他的功业。]=],
		},
		{
			title = "意义",
			text = [=[在索拉丁之前，只有{link:horde}部落{/link}。在他之后，才有了一个民族。他与精灵的同盟赢得了{link:troll-wars}巨魔战争{/link}，为{link:humans}人类{/link}带来了魔法的知识，他的血脉在数千年中一直受到{link:quel-thalas}奎尔萨拉斯{/link}精灵的尊崇。{link:razorfen-downs}高地{/link}与{link:hillsbrad-foothills}希尔斯布莱德{/link}之间的那道巨墙至今仍以他的名字命名。]=],
		},
		{
			title = "部落的统一",
			text = [=[{link:arathi-highlands}阿拉希{/link}部族与阿曼尼作战的时间比其他任何{link:horde}部落{/link}都长，索拉丁在与{link:trolls}巨魔{/link}接壤的边疆学会了战争。他看到了其他酋长不愿看到的事实：巨魔会把各个部落逐一消灭。他用尽一切手段将他们聚集在一起。有些部落他以联姻赢得，有些以土地和财富的许诺赢得，还有一些则是在战场上击败的。对于被他击败的人，他并不羞辱。他让他们的首领成为自己的将军，于是他们成了他最忠诚的部下。]=],
		},
		{
			title = "斯托姆",
			text = [=[索拉丁将都城建在{link:razorfen-downs}高地{/link}干燥的{link:burning-steppes}平原{/link}上，远离{link:trolls}巨魔{/link}设下埋伏的茂密森林。{link:stromgarde-keep}斯托姆{/link}要塞成了一处避难之所，{link:humans}人类{/link}从整片大陆来到这里。也正是在这里，人类第一次学会了奥术之道。]=],
		},
		{
			title = "巨魔战争",
			text = [=[当阿曼尼进攻{link:quel-thalas}奎尔萨拉斯{/link}时，精灵派使者来到{link:stromgarde-keep}斯托姆{/link}。他们承诺向一百名{link:humans}人类{/link}传授魔法之道，以换取{link:arathor}阿拉索{/link}的刀剑。索拉丁接受了。他的大军在精灵领土南部打击{link:trolls}巨魔{/link}，将他们引入{link:alterac-mountains}奥特兰克山脉{/link}的山麓，精灵和新晋的人类法师则从另一侧向他们发起了攻击。阿曼尼被击溃了。为表感激，精灵们向索拉丁的血脉立下了友谊的誓言。]=],
		},
		{
			title = "遗产",
			text = [=[索拉丁希望{link:stromgarde-keep}斯托姆{/link}始终是他王国的中心，他担心帝国扩张得过于辽阔。然而在他之后，他的人民还是走了出去，建立了{link:dalaran}达拉然{/link}、{link:gilneas}吉尔尼斯{/link}、{link:kul-tiras}库尔提拉斯{/link}、{link:alterac-mountains}奥特兰克{/link}和洛丹伦。斯托姆衰落了。最终，他血脉的最后传人离开了这里，航向南方，建立了一个新的王国。许多个世纪之后，这一血脉的最后一人{link:anduin-lothar}安度因·洛萨{/link}在{link:second-war}第二次战争{/link}中率领了{link:lordaeron}洛丹伦{/link}{link:alliance}联盟{/link}。]=],
		},
		{ title = "未载之事", text = "史书对索拉丁的家人、他的晚年以及他的死都着墨甚少。本条目不对此妄加揣测。" },
	},
	chapters = {
		{
			title = "索拉丁徽记",
			hint = "追寻那枚刻有第一位国王之名的破碎徽记。",
			text = [=[在守护托尔{link:baine-bloodhoof}贝恩{/link}家族陵墓的封印之中，有一枚以索拉丁命名的徽记。王子{link:prince-galen-trollbane}加林{/link}将它打碎，把碎片分给了他最后的守军。碎片从他们的尸体上被取走，一位{link:horde}部落{/link}的{link:trolls}巨魔{/link}萨满祭司又将它们重新合为一体。第一位国王的名字，成了他的人民曾经击败的巨魔手中的一把钥匙。]=],
