Translate("zhCN", "thoras-trollbane", {
	title = "索拉斯·托尔贝恩",
	subtitle = "已故的激流堡国王",
	allegiance = "激流堡王国 · 托尔贝恩家族",
	aliases = { "索拉斯", "国王索拉斯" },
	sections = {
		{
			title = "概述",
			text = [=[索拉斯·托尔贝恩是{link:stromgarde-keep}激流堡{/link}的国王，是那个自{link:arathor}阿拉索{/link}王室血脉离开后便一直统治这座城市的古老家族的继承人。他是一位战士国王，统治着一片尽是坚韧士兵的土地。如今他已经死去，他的王国也随他一同消亡了。他长眠在激流堡礼拜堂后方密室中一座封印的陵墓里，身旁放着他家族的宝剑。]=],
		},
		{
			title = "意义",
			text = [=[索拉斯是组建{link:lordaeron}洛丹伦{/link}{link:alliance}联盟{/link}对抗{link:horde}部落{/link}的统治者之一。他的家族是伊格纳乌斯的后裔，伊格纳乌斯是{link:troll-wars}巨魔战争{/link}中的一位将军，正是他的利刃{link:trol-kalar}托卡拉尔{/link}为这个家族赢得了它的姓氏。对{link:azeroth}艾泽拉斯{/link}的{link:trolls}巨魔{/link}来说，托尔{link:baine-bloodhoof}贝恩{/link}这个名字至今仍是一个诅咒。]=],
		},
		{
			title = "事迹",
			text = [=[• 他在{link:second-war}第二次战争{/link}中率领{link:stromgarde-keep}激流堡{/link}加入了{link:alliance}洛丹伦联盟{/link}。
• 战后，当联盟为{link:internment-camps}收容所{/link}及其开销争执不休时，他让激流堡退出了联盟。
• 他与伊格纳乌斯的宝剑{link:trol-kalar}托卡拉尔{/link}一同下葬。]=],
		},
		{ title = "未载之事", text = "关于这段时期，没有任何编年史记载索拉斯·托尔贝恩是怎样死去的。他的人民只说他已经不在了。" },
	},
	chapters = {
		{
			title = "密室中的陵墓",
			hint = "站在激流堡最后一位国王的陵墓前。",
			text = [=[国王索拉斯的陵墓位于守军城区礼拜堂的后方，由家族的看守者守护着。陵墓的正面刻着纹路，若没有他儿子分散出去的那些徽记，任何人都无法将其打开。陵墓上一双石雕之手紧握着的，正是{link:trol-kalar}托卡拉尔{/link}。]=],
		},
	},
	mentions = {
		{ text = "《托尔{link:baine-bloodhoof}贝恩{/link}》，他的死讯" },
		{ text = "{link:trol-kalar}托卡拉尔{/link}" },
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "加林·托尔贝恩王子", note = "他的儿子" },
		{ id = "terenas-menethil", name = "泰瑞纳斯·米奈希尔", note = "他在联盟中的盟友" },
