})

Translate("zhCN", "trol-kalar", {
	title = "托卡拉尔",
	sections = {
		{
			title = "概述",
			text = [=[托卡拉尔是托尔{link:baine-bloodhoof}贝恩{/link}家族的古老宝剑。它的名字在{link:trolls}巨魔{/link}自己的语言中意为“巨魔杀手”。在{link:arathor}阿拉索{/link}的战争中，{link:stromgarde-keep}斯托姆{/link}的伊格纳乌斯领主手持此剑，他是巨魔所面对过的最可怕的敌人，这柄剑也为他的家族赢得了姓氏。]=],
		},
		{
			title = "陵墓",
			text = [=[{link:thoras-trollbane}国王索拉斯{/link}死后，托卡拉尔被安放在{link:stromgarde-keep}激流堡{/link}礼拜堂后方密室中的陵墓里，由一双石雕之手紧握着。陵墓以结界封印，只有一枚徽记能够将其开启。王子{link:prince-galen-trollbane}加林{/link}将这枚徽记一分为四：斯托姆徽记、{link:thoradin}索拉丁{/link}徽记、{link:arathor}阿拉索{/link}徽记和托尔{link:baine-bloodhoof}贝恩{/link}徽记。其中一枚随城市一起落入了{link:syndicate}辛迪加{/link}之手。其余几枚，他分别交给了他的士兵、他的骑兵首领和他自己。四枚合在一起，便成为一枚：伊格纳乌斯徽记。]=],
		},
		{
			title = "当今",
			text = [=[{link:darkspear-trolls}暗矛{/link}的{link:vol-jin}沃金{/link}想要这柄剑。他已派猎手赞古前往{link:hammerfall}落锤镇{/link}夺取它，好让{link:stromgarde-keep}斯托姆{/link}的{link:trolls}巨魔{/link}杀手调转锋芒，去对付{link:zul-gurub}祖尔格拉布{/link}的古拉巴什巨魔。]=],
		},
	},
})

Translate("zhCN", "witherbark-trolls", {
	title = "枯木巨魔",
	aliases = { "枯木", "枯木部族" },
	sections = {
		{
			title = "概述",
			text = [=[枯木是一个森林{link:trolls}巨魔{/link}部族，生活在{link:arathi-highlands}阿拉希高地{/link}的东南部。他们的村庄矗立在那里的丘陵之间，村后有洞穴，部族的战团首领们在那里聚集。自{link:thoradin}索拉丁{/link}的时代起，巨魔就一直在与{link:stromgarde-keep}斯托姆{/link}的{link:humans}人类{/link}作战，枯木巨魔至今仍将那场战争铭记于心。]=],
		},
		{
			title = "他们的习俗",
			text = [=[部族中有掷斧者、猎头者、狂暴战士，还有携带药囊和血石护符的巫医。暗影猎手在完成成年仪式时会得到一把特殊的小刀。两位战团首领扎拉斯·枯木和杀戮者尼玛尔率领他们出征。]=],
		},
		{
			title = "当今",
			text = [=[枯木巨魔曾与{link:orcs}兽人{/link}并肩作战，后来又离开了他们。如今，他们已与{link:boulderfist-ogres}石拳食人魔{/link}联手，要把{link:horde}部落{/link}赶出{link:hammerfall}落锤镇{/link}。他们的战士与{link:ogres}食人魔{/link}共用{link:boulder-gor}博德戈尔{/link}土丘，部族的狂暴战士也与食人魔一起驻守在{link:stromgarde-keep}激流堡{/link}的废墟中。落锤镇的{link:drum-fel}杜拉姆法尔{/link}已将他们定为自己这场战争的首要目标。]=],
		},
	},
})

Translate("zhCN", "boulderfist-ogres", {
	title = "石拳食人魔",
	aliases = { "石拳", "石拳氏族" },
	sections = {
		{
			title = "概述",
			text = [=[石拳是{link:arathi-highlands}阿拉希高地{/link}上最强大的{link:ogres}食人魔{/link}氏族。他们占据着{link:boulder-gor}博德戈尔{/link}土丘、{link:boulderfist-hall}石拳大厅{/link}的洞穴以及{link:stromgarde-keep}激流堡{/link}废城的大片区域。没有任何编年史记载他们是何时来到{link:razorfen-downs}高地{/link}的。]=],
		},
		{
			title = "他们的习俗",
			text = [=[他们当中有蛮兵、执行者、重殴者和领主，还有学会了使用掠夺来的宝物的法师和萨满。他们的萨满十分珍视从{link:arathor}阿拉索{/link}之塔中拿走的天蓝玛瑙。在{link:boulderfist-hall}石拳大厅{/link}，{link:ogres}食人魔{/link}法师{link:kor-gresh-coldrage}考格雷什{/link}用一根偷来的魔杖投掷寒冰。在{link:stromgarde-keep}激流堡{/link}，食人魔{link:or-kalar}奥卡拉尔{/link}以{link:mug-thol}玛格索尔{/link}的名义指挥他们，玛格索尔是一位并非来自{link:razorfen-downs}高地{/link}的军阀。]=],
		},
		{
			title = "当今",
			text = [=[石拳食人魔为争夺城市废墟而与{link:stromgarde-keep}激流堡{/link}的士兵和{link:syndicate}辛迪加{/link}作战，他们还与{link:witherbark-trolls}枯木巨魔{/link}联手对付{link:hammerfall}落锤镇{/link}。考沃克、碾压者摩{link:locke-okarr}洛克{/link}、鲁尔·巨石和弗尔伯利是他们首领中令人畏惧的几位。]=],
		},
	},
})

Translate("zhCN", "drywhisker-kobolds", {
	title = "枯须狗头人",
	aliases = { "枯须" },
	sections = {
		{
			title = "概述",
			text = [=[枯须是一个{link:kobolds}狗头人{/link}部族，在{link:razorfen-downs}高地{/link}最东北部的{link:drywhisker-gorge}枯须峡谷{/link}中挖掘。他们是勘测员和挖掘工，其中有一个名叫燧石匕首的地卜师，能够操纵火焰。]=],
		},
		{
			title = "碎片",
			text = [=[枯须狗头人不只是矿工。在峡谷深处，他们守护着一簇闪着虹彩的水晶碎片，并随身携带着蕴含奇异力量的微粒。被禁锢在{link:razorfen-downs}高地{/link}之下的那个存在称他们为囚禁她的巨人的盟友。其中三个{link:kobolds}狗头人{/link}甚至跟随在石之{link:the-night-watch}守望者{/link}{link:fozruk}弗兹鲁克{/link}本人身边。没有人知道巨人为了他们的效劳给了狗头人什么，也没有人知道狗头人是否明白自己在侍奉谁。]=],
		},
	},
})

Translate("zhCN", "league-of-arathor", {
	title = "阿拉索联军",
	sections = {
		{
			title = "概述",
			text = [=[阿拉索联军是{link:stromgarde-keep}激流堡{/link}王国残部的战斗力量。它的士兵是一个骄傲王国的继承者，而这个王国的首都如今已被{link:ogres}食人魔{/link}和匪徒占据。他们发誓要为激流堡的人民和{link:alliance}联盟{/link}夺回{link:razorfen-downs}高地{/link}。]=],
		},
		{
			title = "他们的大业",
			text = [=[联军在{link:field-marshal-oslight}奥斯莱特元帅{/link}的统领下驻扎于{link:refuge-pointe}避难谷地{/link}。它的第一场战斗是为了{link:arathi-basin}阿拉希盆地{/link}，那是一片拥有农场、矿洞、{link:the-cauldron}熔炉{/link}和森林的肥沃{link:stranglethorn-vale}山谷{/link}。联军打算为它在{link:stormwind-city}暴风城{/link}的盟友夺取盆地的财富，并通过暴风城惠及整个{link:alliance}联盟{/link}。它的士兵占据着山谷边缘以{link:stromgarde-keep}激流堡{/link}王室命名的托尔{link:baine-bloodhoof}贝恩{/link}大厅。]=],
		},
		{
			title = "当今",
			text = [=[联军在盆地中与{link:defilers}被遗忘者污染者{/link}对峙。它的军需官{link:brother-sammuel}萨缪尔{/link}·霍克为参战者提供补给，它的中士们则敦促每一名士兵抢在敌人之前出击。]=],
		},
	},
})

Translate("zhCN", "defilers", {
	title = "污染者",
	aliases = { "污染者", "被遗忘者污染者" },
	sections = {
		{
			title = "概述",
			text = [=[污染者是{link:forsaken}被遗忘者{/link}的精锐部队，在{link:varimathras}瓦里玛萨斯{/link}的监视下被派往{link:arathi-highlands}阿拉希高地{/link}。他们为争夺{link:arathi-basin}阿拉希盆地{/link}而与{link:league-of-arathor}阿拉索联军{/link}作战。他们的目的并非{link:orcs}兽人{/link}的战争，而是他们自己女王的战争：切断北方{link:humans}人类{/link}与南方{link:dwarves}矮人{/link}盟友之间的联系，并为{link:undercity}幽暗城{/link}夺取盆地的财富。]=],
		},
		{
			title = "他们的营地",
			text = [=[污染者在{link:deathmaster-dwire}屠杀者杜维尔{/link}的统领下，将总部设在{link:hammerfall}落锤镇{/link}，与前哨中的{link:orcs}兽人{/link}和{link:trolls}巨魔{/link}比邻而居。在盆地中，他们占据着污染者之穴。他们的军需官卢瑟弗·图恩为替他们作战的人提供补给，死亡猎手莫提斯则在德维尔身边效力。]=],
		},
		{
			title = "当今",
			text = [=[{link:deathmaster-dwire}德维尔{/link}相信，即便是{link:refuge-pointe}避难谷地{/link}那座小小的营地，有朝一日也可能威胁到{link:horde}部落{/link}。污染者决心确保{link:arathi-highlands}阿拉希{/link}永远不会再成为{link:humans}人类{/link}的家园。]=],
		},
	},
})
